29	/*
30	 * This sample implements a conjugate gradient solver on GPU
31	 * using CUBLAS and CUSPARSE with CUDA Graphs
32	 *
33	 */
34	
35	// includes, system
36	#include <stdio.h>
37	#include <stdlib.h>
38	#include <string.h>
39	
40	/* Using updated (v2) interfaces to cublas */
41	#include <cublas_v2.h>
42	#include <cuda_runtime.h>
43	#include <cusparse.h>
44	
45	// Utilities and system includes
46	#include <helper_cuda.h>  // helper function CUDA error checking and initialization
47	#include <helper_functions.h>  // helper for shared functions common to CUDA Samples
48	
49	
50	const char *sSDKname = "conjugateGradientCudaGraphs";
51	
52	#ifndef WITH_GRAPH
53	#define WITH_GRAPH 1
54	#endif
55	
56	/* genTridiag: generate a random tridiagonal symmetric matrix */
57	void genTridiag(int *I, int *J, float *val, int N, int nz) {
58	  I[0] = 0, J[0] = 0, J[1] = 1;
59	  val[0] = (float)rand() / RAND_MAX + 10.0f;
60	  val[1] = (float)rand() / RAND_MAX;
61	  int start;
62	
63	  for (int i = 1; i < N; i++) {
64	    if (i > 1) {
65	      I[i] = I[i - 1] + 3;
66	    } else {
67	      I[1] = 2;
68	    }
69	
70	    start = (i - 1) * 3 + 2;
71	    J[start] = i - 1;
72	    J[start + 1] = i;
73	
74	    if (i < N - 1) {
75	      J[start + 2] = i + 1;
76	    }
77	
78	    val[start] = val[start - 1];
79	    val[start + 1] = (float)rand() / RAND_MAX + 10.0f;
80	
81	    if (i < N - 1) {
82	      val[start + 2] = (float)rand() / RAND_MAX;
83	    }
84	  }
85	
86	  I[N] = nz;
87	}
88	
89	__global__ void initVectors(float *rhs, float *x, int N) {
90	  size_t gid = blockIdx.x * blockDim.x + threadIdx.x;
91	
92	  for (size_t i = gid; i < N; i += gridDim.x * blockDim.x) {
93	    rhs[i] = 1.0;
94	    x[i] = 0.0;
95	  }
96	}
97	
98	__global__ void r1_div_x(float *r1, float *r0, float *b) {
99	  int gid = blockIdx.x * blockDim.x + threadIdx.x;
100	  if (gid == 0) {
101	    b[0] = r1[0] / r0[0];
102	  }
103	}
104	
105	__global__ void a_minus(float *a, float *na) {
106	  int gid = blockIdx.x * blockDim.x + threadIdx.x;
107	  if (gid == 0) {
108	    na[0] = -(a[0]);
109	  }
110	}
