112	int main(int argc, char **argv) {
113	  int N = 0, nz = 0, *I = NULL, *J = NULL;
114	  float *val = NULL;
115	  const float tol = 1e-5f;
116	  const int max_iter = 10000;
117	  float *x;
118	  float *rhs;
119	  float r1;
120	
121	  int *d_col, *d_row;
122	  float *d_val, *d_x;
123	  float *d_r, *d_p, *d_Ax;
124	  int k;
125	  float alpha, beta, alpham1;
126	
127	  cudaStream_t stream1, streamForGraph;
128	
129	  // This will pick the best possible CUDA capable device
130	  cudaDeviceProp deviceProp;
131	  int devID = findCudaDevice(argc, (const char **)argv);
132	
133	  if (devID < 0) {
134	    printf("exiting...\n");
135	    exit(EXIT_SUCCESS);
136	  }
137	
138	  checkCudaErrors(cudaGetDeviceProperties(&deviceProp, devID));
139	
140	  // Statistics about the GPU device
141	  printf(
142	      "> GPU device has %d Multi-Processors, SM %d.%d compute capabilities\n\n",
143	      deviceProp.multiProcessorCount, deviceProp.major, deviceProp.minor);
144	
145	  /* Generate a random tridiagonal symmetric matrix in CSR format */
146	  N = 1048576;
147	  nz = (N - 2) * 3 + 4;
148	  I = (int *)malloc(sizeof(int) * (N + 1));
149	  J = (int *)malloc(sizeof(int) * nz);
150	  val = (float *)malloc(sizeof(float) * nz);
151	  genTridiag(I, J, val, N, nz);
152	
153	  x = (float *)malloc(sizeof(float) * N);
154	  rhs = (float *)malloc(sizeof(float) * N);
155	
156	  for (int i = 0; i < N; i++) {
157	    rhs[i] = 1.0;
158	    x[i] = 0.0;
159	  }
160	
161	  /* Get handle to the CUBLAS context */
162	  cublasHandle_t cublasHandle = 0;
163	  cublasStatus_t cublasStatus;
164	  cublasStatus = cublasCreate(&cublasHandle);
165	
166	  checkCudaErrors(cublasStatus);
167	
168	  /* Get handle to the CUSPARSE context */
169	  cusparseHandle_t cusparseHandle = 0;
170	  cusparseStatus_t cusparseStatus;
171	  cusparseStatus = cusparseCreate(&cusparseHandle);
172	
173	  checkCudaErrors(cusparseStatus);
174	
175	  checkCudaErrors(cudaStreamCreate(&stream1));
176	
177	  checkCudaErrors(cudaMalloc((void **)&d_col, nz * sizeof(int)));
178	  checkCudaErrors(cudaMalloc((void **)&d_row, (N + 1) * sizeof(int)));
179	  checkCudaErrors(cudaMalloc((void **)&d_val, nz * sizeof(float)));
180	  checkCudaErrors(cudaMalloc((void **)&d_x, N * sizeof(float)));
181	  checkCudaErrors(cudaMalloc((void **)&d_r, N * sizeof(float)));
182	  checkCudaErrors(cudaMalloc((void **)&d_p, N * sizeof(float)));
183	  checkCudaErrors(cudaMalloc((void **)&d_Ax, N * sizeof(float)));
184	
185	  float *d_r1, *d_r0, *d_dot, *d_a, *d_na, *d_b;
186	  checkCudaErrors(cudaMalloc((void **)&d_r1, sizeof(float)));
187	  checkCudaErrors(cudaMalloc((void **)&d_r0, sizeof(float)));
188	  checkCudaErrors(cudaMalloc((void **)&d_dot, sizeof(float)));
189	  checkCudaErrors(cudaMalloc((void **)&d_a, sizeof(float)));
190	  checkCudaErrors(cudaMalloc((void **)&d_na, sizeof(float)));
191	  checkCudaErrors(cudaMalloc((void **)&d_b, sizeof(float)));
192	
193	  /* Wrap raw data into cuSPARSE generic API objects */
194	  cusparseSpMatDescr_t matA = NULL;
195	  checkCudaErrors(cusparseCreateCsr(
196	      &matA, N, N, nz, d_row, d_col, d_val, CUSPARSE_INDEX_32I,
197	      CUSPARSE_INDEX_32I, CUSPARSE_INDEX_BASE_ZERO, CUDA_R_32F));
198	  cusparseDnVecDescr_t vecx = NULL;
199	  checkCudaErrors(cusparseCreateDnVec(&vecx, N, d_x, CUDA_R_32F));
200	  cusparseDnVecDescr_t vecp = NULL;
201	  checkCudaErrors(cusparseCreateDnVec(&vecp, N, d_p, CUDA_R_32F));
202	  cusparseDnVecDescr_t vecAx = NULL;
203	  checkCudaErrors(cusparseCreateDnVec(&vecAx, N, d_Ax, CUDA_R_32F));
204	
205	  /* Allocate workspace for cuSPARSE */
206	  size_t bufferSize = 0;
207	  checkCudaErrors(cusparseSpMV_bufferSize(
208	      cusparseHandle, CUSPARSE_OPERATION_NON_TRANSPOSE, &alpha, matA, vecx,
209	      &beta, vecAx, CUDA_R_32F, CUSPARSE_MV_ALG_DEFAULT, &bufferSize));
210	  void *buffer = NULL;
211	  checkCudaErrors(cudaMalloc(&buffer, bufferSize));
212	
213	  cusparseMatDescr_t descr = 0;
214	  checkCudaErrors(cusparseCreateMatDescr(&descr));
215	
216	  checkCudaErrors(cusparseSetMatType(descr, CUSPARSE_MATRIX_TYPE_GENERAL));
217	  checkCudaErrors(cusparseSetMatIndexBase(descr, CUSPARSE_INDEX_BASE_ZERO));
218	
219	  int numBlocks = 0, blockSize = 0;
220	  checkCudaErrors(
221	      cudaOccupancyMaxPotentialBlockSize(&numBlocks, &blockSize, initVectors));
222	
223	  checkCudaErrors(cudaMemcpyAsync(d_col, J, nz * sizeof(int),
224	                                  cudaMemcpyHostToDevice, stream1));
225	  checkCudaErrors(cudaMemcpyAsync(d_row, I, (N + 1) * sizeof(int),
226	                                  cudaMemcpyHostToDevice, stream1));
227	  checkCudaErrors(cudaMemcpyAsync(d_val, val, nz * sizeof(float),
228	                                  cudaMemcpyHostToDevice, stream1));
229	
230	  initVectors<<<numBlocks, blockSize, 0, stream1>>>(d_r, d_x, N);
231	
232	  alpha = 1.0;
233	  alpham1 = -1.0;
234	  beta = 0.0;
235	
236	  checkCudaErrors(cusparseSetStream(cusparseHandle, stream1));
237	  checkCudaErrors(cusparseSpMV(
238	    cusparseHandle, CUSPARSE_OPERATION_NON_TRANSPOSE, &alpha, matA, vecx,
239	    &beta, vecAx, CUDA_R_32F, CUSPARSE_MV_ALG_DEFAULT, &buffer));
240	
241	  checkCudaErrors(cublasSetStream(cublasHandle, stream1));
242	  checkCudaErrors(cublasSaxpy(cublasHandle, N, &alpham1, d_Ax, 1, d_r, 1));
243	
244	  checkCudaErrors(
245	      cublasSetPointerMode(cublasHandle, CUBLAS_POINTER_MODE_DEVICE));
246	  checkCudaErrors(cublasSdot(cublasHandle, N, d_r, 1, d_r, 1, d_r1));
247	
248	  k = 1;
249	  // First Iteration when k=1 starts
250	  checkCudaErrors(cublasScopy(cublasHandle, N, d_r, 1, d_p, 1));
251	  checkCudaErrors(cusparseSpMV(
252	    cusparseHandle, CUSPARSE_OPERATION_NON_TRANSPOSE, &alpha, matA, vecp,
253	    &beta, vecAx, CUDA_R_32F, CUSPARSE_MV_ALG_DEFAULT, &buffer));
254	
255	  checkCudaErrors(cublasSdot(cublasHandle, N, d_p, 1, d_Ax, 1, d_dot));
256	
257	  r1_div_x<<<1, 1, 0, stream1>>>(d_r1, d_dot, d_a);
258	
259	  checkCudaErrors(cublasSaxpy(cublasHandle, N, d_a, d_p, 1, d_x, 1));
260	
261	  a_minus<<<1, 1, 0, stream1>>>(d_a, d_na);
262	
263	  checkCudaErrors(cublasSaxpy(cublasHandle, N, d_na, d_Ax, 1, d_r, 1));
264	
265	  checkCudaErrors(cudaMemcpyAsync(d_r0, d_r1, sizeof(float),
266	                                  cudaMemcpyDeviceToDevice, stream1));
267	
268	  checkCudaErrors(cublasSdot(cublasHandle, N, d_r, 1, d_r, 1, d_r1));
269	
270	  checkCudaErrors(cudaMemcpyAsync(&r1, d_r1, sizeof(float),
271	                                  cudaMemcpyDeviceToHost, stream1));
272	  checkCudaErrors(cudaStreamSynchronize(stream1));
273	  printf("iteration = %3d, residual = %e\n", k, sqrt(r1));
274	  // First Iteration when k=1 ends
275	  k++;
276	
277	#if WITH_GRAPH
278	  cudaGraph_t initGraph;
279	  checkCudaErrors(cudaStreamCreate(&streamForGraph));
280	  checkCudaErrors(cublasSetStream(cublasHandle, stream1));
281	  checkCudaErrors(cusparseSetStream(cusparseHandle, stream1));
282	  checkCudaErrors(cudaStreamBeginCapture(stream1, cudaStreamCaptureModeGlobal));
283	
284	  r1_div_x<<<1, 1, 0, stream1>>>(d_r1, d_r0, d_b);
285	  cublasSetPointerMode(cublasHandle, CUBLAS_POINTER_MODE_DEVICE);
286	  checkCudaErrors(cublasSscal(cublasHandle, N, d_b, d_p, 1));
287	  cublasSetPointerMode(cublasHandle, CUBLAS_POINTER_MODE_HOST);
288	  checkCudaErrors(cublasSaxpy(cublasHandle, N, &alpha, d_r, 1, d_p, 1));
289	  cublasSetPointerMode(cublasHandle, CUBLAS_POINTER_MODE_DEVICE);
290	
291	  checkCudaErrors(
292	      cusparseSetPointerMode(cusparseHandle, CUSPARSE_POINTER_MODE_HOST));
293	  checkCudaErrors(cusparseSpMV(
294	    cusparseHandle, CUSPARSE_OPERATION_NON_TRANSPOSE, &alpha, matA, vecp,
295	    &beta, vecAx, CUDA_R_32F, CUSPARSE_MV_ALG_DEFAULT, &buffer));
296	
297	  checkCudaErrors(cudaMemsetAsync(d_dot, 0, sizeof(float), stream1));
298	  checkCudaErrors(cublasSdot(cublasHandle, N, d_p, 1, d_Ax, 1, d_dot));
299	
300	  r1_div_x<<<1, 1, 0, stream1>>>(d_r1, d_dot, d_a);
301	
302	  checkCudaErrors(cublasSaxpy(cublasHandle, N, d_a, d_p, 1, d_x, 1));
303	
304	  a_minus<<<1, 1, 0, stream1>>>(d_a, d_na);
305	
306	  checkCudaErrors(cublasSaxpy(cublasHandle, N, d_na, d_Ax, 1, d_r, 1));
307	
308	  checkCudaErrors(cudaMemcpyAsync(d_r0, d_r1, sizeof(float),
309	                                  cudaMemcpyDeviceToDevice, stream1));
310	  checkCudaErrors(cudaMemsetAsync(d_r1, 0, sizeof(float), stream1));
311	
312	  checkCudaErrors(cublasSdot(cublasHandle, N, d_r, 1, d_r, 1, d_r1));
313	
314	  checkCudaErrors(cudaMemcpyAsync((float *)&r1, d_r1, sizeof(float),
315	                                  cudaMemcpyDeviceToHost, stream1));
316	
317	  checkCudaErrors(cudaStreamEndCapture(stream1, &initGraph));
318	  cudaGraphExec_t graphExec;
319	  checkCudaErrors(cudaGraphInstantiate(&graphExec, initGraph, NULL, NULL, 0));
320	#endif
321	
322	  checkCudaErrors(cublasSetStream(cublasHandle, stream1));
323	  checkCudaErrors(cusparseSetStream(cusparseHandle, stream1));
324	
325	  while (r1 > tol * tol && k <= max_iter) {
326	#if WITH_GRAPH
327	    checkCudaErrors(cudaGraphLaunch(graphExec, streamForGraph));
328	    checkCudaErrors(cudaStreamSynchronize(streamForGraph));
329	#else
330	    r1_div_x<<<1, 1, 0, stream1>>>(d_r1, d_r0, d_b);
331	    cublasSetPointerMode(cublasHandle, CUBLAS_POINTER_MODE_DEVICE);
332	    checkCudaErrors(cublasSscal(cublasHandle, N, d_b, d_p, 1));
333	
334	    cublasSetPointerMode(cublasHandle, CUBLAS_POINTER_MODE_HOST);
335	    checkCudaErrors(cublasSaxpy(cublasHandle, N, &alpha, d_r, 1, d_p, 1));
336	
337	    checkCudaErrors(cusparseSpMV(
338	      cusparseHandle, CUSPARSE_OPERATION_NON_TRANSPOSE, &alpha, matA, vecp,
339	      &beta, vecAx, CUDA_R_32F, CUSPARSE_MV_ALG_DEFAULT, &buffer));
340	
341	    cublasSetPointerMode(cublasHandle, CUBLAS_POINTER_MODE_DEVICE);
342	    checkCudaErrors(cublasSdot(cublasHandle, N, d_p, 1, d_Ax, 1, d_dot));
343	
344	    r1_div_x<<<1, 1, 0, stream1>>>(d_r1, d_dot, d_a);
345	
346	    checkCudaErrors(cublasSaxpy(cublasHandle, N, d_a, d_p, 1, d_x, 1));
347	
348	    a_minus<<<1, 1, 0, stream1>>>(d_a, d_na);
349	    checkCudaErrors(cublasSaxpy(cublasHandle, N, d_na, d_Ax, 1, d_r, 1));
350	
351	    checkCudaErrors(cudaMemcpyAsync(d_r0, d_r1, sizeof(float),
352	                                    cudaMemcpyDeviceToDevice, stream1));
353	
354	    checkCudaErrors(cublasSdot(cublasHandle, N, d_r, 1, d_r, 1, d_r1));
355	    checkCudaErrors(cudaMemcpyAsync((float *)&r1, d_r1, sizeof(float),
356	                                    cudaMemcpyDeviceToHost, stream1));
357	    checkCudaErrors(cudaStreamSynchronize(stream1));
358	#endif
359	    printf("iteration = %3d, residual = %e\n", k, sqrt(r1));
360	    k++;
361	  }
362	
363	#if WITH_GRAPH
364	  checkCudaErrors(cudaMemcpyAsync(x, d_x, N * sizeof(float),
365	                                  cudaMemcpyDeviceToHost, streamForGraph));
366	  checkCudaErrors(cudaStreamSynchronize(streamForGraph));
367	#else
368	  checkCudaErrors(cudaMemcpyAsync(x, d_x, N * sizeof(float),
369	                                  cudaMemcpyDeviceToHost, stream1));
370	  checkCudaErrors(cudaStreamSynchronize(stream1));
371	#endif
372	
373	  float rsum, diff, err = 0.0;
374	
375	  for (int i = 0; i < N; i++) {
376	    rsum = 0.0;
377	
378	    for (int j = I[i]; j < I[i + 1]; j++) {
379	      rsum += val[j] * x[J[j]];
380	    }
381	
382	    diff = fabs(rsum - rhs[i]);
383	
384	    if (diff > err) {
385	      err = diff;
386	    }
387	  }
388	
389	#if WITH_GRAPH
390	  checkCudaErrors(cudaGraphExecDestroy(graphExec));
391	  checkCudaErrors(cudaGraphDestroy(initGraph));
392	  checkCudaErrors(cudaStreamDestroy(streamForGraph));
393	#endif
394	  checkCudaErrors(cudaStreamDestroy(stream1));
395	  cusparseDestroy(cusparseHandle);
396	  cublasDestroy(cublasHandle);
397	
398	  if (matA       ) { checkCudaErrors(cusparseDestroySpMat(matA)); }
399	  if (vecx       ) { checkCudaErrors(cusparseDestroyDnVec(vecx)); }
400	  if (vecAx      ) { checkCudaErrors(cusparseDestroyDnVec(vecAx)); }
401	  if (vecp       ) { checkCudaErrors(cusparseDestroyDnVec(vecp)); }
402	
403	  free(I);
404	  free(J);
405	  free(val);
406	  free(x);
407	  free(rhs);
408	  cudaFree(d_col);
409	  cudaFree(d_row);
410	  cudaFree(d_val);
411	  cudaFree(d_x);
412	  cudaFree(d_r);
413	  cudaFree(d_p);
414	  cudaFree(d_Ax);
415	
416	  printf("Test Summary:  Error amount = %f\n", err);
417	  exit((k <= max_iter) ? 0 : 1);
418	}
